questionvariables.text:
dp(x, n) := float(round((x+10^(-8))*10^n)/10^n);

rain_rain: 90+rand(50);
norain_norain: 150+rand(50);
rr: 365-rain_rain-norain_norain;
rain_norain: floor(rr*rand([0.2,0.25,0.3,0.35,0.4,0.45,0.55,0.6,0.65]));
norain_rain: rr-rain_norain;
total: rain_rain+norain_norain+rain_norain+norain_rain;
f_rain: rain_rain+rain_norain;
f_norain: norain_rain+norain_norain;
a_rain: rain_rain+norain_rain;
a_norain: rain_norain+norain_norain;

row_rain: round([rain_rain,rain_norain]/f_rain*100);
row_norain: round([norain_rain,norain_norain]/f_norain*100);
row_total: round([a_rain,a_norain]/total*100);

col_rain: round([rain_rain,norain_rain]/a_rain*100);
col_norain: round([rain_norain,norain_norain]/a_norain*100);
col_total: round([f_rain,f_norain]/total*100);

aa_forecast: rand(["Rain","No Rain"]);
aa_actual: rand(["Rain","No Rain"]);

bb_type: rand(["forecast","actual weather"]);
bb_typeo: if bb_type="forecast" then "actual weather" else "forecast";
bb_cond: rand(["Rain","No Rain"]);
bb_table: if bb_type="forecast" then 2 else 1;
bb_rc: if bb_type="forecast" then "columns" else "rows";

cc: rand(["correct","incorrect"]);
cc_type: if cc="correct" then "the same" else "different";

ta1: if aa_forecast="Rain" and aa_actual="Rain" then row_rain[1] elseif aa_forecast="Rain" and aa_actual="No Rain" then row_rain[2] elseif aa_forecast="No Rain" and aa_actual="Rain" then row_norain[1] elseif aa_forecast="No Rain" and aa_actual="No Rain" then row_norain[2];
ta2: if bb_type="forecast" and bb_cond="Rain" then col_total[1] elseif bb_type="forecast" and bb_cond="No Rain" then col_total[2] elseif bb_type="actual weather" and bb_cond="Rain" then row_total[1] elseif bb_type="actual weather" and bb_cond="No Rain" then row_total[2];
ta3: if cc="correct" then 100*(row_rain[1]/100*col_total[1]/100+row_norain[2]/100*col_total[2]/100) else 100*(row_rain[2]/100*col_total[1]/100+row_norain[1]/100*col_total[2]/100);
ta3: round(ta3+10^(-8));
